		SELECT *
   		FROM (
      	  SELECT ROWNUM rn, a.*
      	  FROM (
             SELECT review_no, review_score, review_content, review_date, review_image, product_no, member_name, member_id
             FROM tbl_review
             WHERE product_no = #{productNo}
             ORDER BY review_date DESC
    	     ) a
	   	 )
	  	  WHERE rn BETWEEN #{start} AND #{end}

 	 	SELECT COUNT(*)
	  	FROM tbl_review
 		WHERE product_no = #{productNo}

mapper.update:
UPDATE tbl_product p
SET p.product_score = (
    SELECT NVL(ROUND(AVG(r.review_score), 1), 0)
    FROM tbl_review r
    WHERE r.product_no = #{productNo}
)
WHERE p.product_no = #{productNo}
